# Generated by build.py from recipe.yml for recipe sftp-log-in-with-a-public-key. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
cmd /c 'ssh-keygen -t rsa -b 3072 -N "" -f host_key'
cmd /c 'ssh-keygen -t rsa -b 3072 -N "" -f alice_key'
cmd /c 'ssh-keygen -t rsa -b 3072 -N "" -f other_key'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--hostkey', 'host_key', '--authorized-keys', 'alice:alice_key.pub', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -k -u alice: --key alice_key --pubkey alice_key.pub sftp://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
